<?php if (!empty($s[3])): ?><form method="post"><?= csrf() ?><input type="hidden" name="a" value="rmphoto"><input type="hidden" name="i" value="<?= $i ?>"><button class="link">Hapus foto</button></form><?php endif; ?>
